"""Erstelle einen Link zu einer Karte im Geoportal des Kantons Bern mit vordefinierten Parametern."""


def get_map_link(name_function: str, params: dict) -> str:
    """Erstelle einen Link zu einer Karte im Geoportal des Kantons Bern mit vordefinierten Parametern.

    Args:
        name_function (str): Name der MCP-Funktion.
        params (dict):  Parameter zur lokalisation des Kartenausschnitts.
                        Erlaubte Parameter: egrid oder (x, y) oder gemeinde -> Lokalisation
                                            scale -> Massstab der Karte
                                            lang -> Sprache der Karte
                                            layers -> Layername

    Returns:
        str: URL-Link zur Kartenansicht im Geoportal des Kantons Bern.
    """
    base_url = "https://www.topo.apps.be.ch/pub/map/?"

    if name_function == "get_natural_hazards_for_egrid":
        egrid = params.get("egrid", "CH294676423526")  # Default EGRID auf Bundeshaus
        scale = params.get("scale", 1000)
        lang = params.get("lang", "de")
        url = f"DIPANU_DIPANUF_KMGDM1=DIPANUF_EGRID={egrid}&addcrosshair=false&scale={scale}&lang={lang}&layers=NATGEFKA_GEFGEB_KMGDM3&legend=True"

    if name_function == "get_borehole_profiles_for_egrid":
        egrid = params.get("egrid", "CH294676423526")  # Default EGRID auf Bundeshaus
        scale = params.get("scale", 1000)
        lang = params.get("lang", "de")
        url = f"DIPANU_DIPANUF_KMGDM1=DIPANUF_EGRID={egrid}&addcrosshair=false&scale={scale}&lang={lang}&layers=GEOSOND_GEOSOND_KMGDM1&legend=True"

    if name_function == "get_property_info_for_egrid":
        egrid = params.get("egrid", "CH294676423526")  # Default EGRID auf Bundeshaus
        scale = params.get("scale", 1000)
        lang = params.get("lang", "de")
        url = f"DIPANU_DIPANUF_KMGDM1=DIPANUF_EGRID={egrid}&addcrosshair=false&scale={scale}&lang={lang}"
    
    if name_function == "get_coordinates_from_nomkl":
        lang = params.get("lang", "de")
        centerx, centery = get_center_from_bbox(params)
        scale = get_scale_from_bbox(params)
        url = f"&addcrosshair=true&scale={scale}&lang={lang}&center={centerx},{centery}&theme=HK_BUNT&gpk=NOMKL_GPK"

    if name_function == "get_subsoil_class_for_egrid":
        egrid = params.get("egrid", "CH294676423526")  # Default EGRID auf Bundeshaus
        scale = params.get("scale", 1000)
        lang = params.get("lang", "de")
        url = f"DIPANU_DIPANUF_KMGDM1=DIPANUF_EGRID={egrid}&addcrosshair=false&scale={scale}&lang={lang}&layers=FRK_SEDIRAS_KMGDM2&legend=True"

    if name_function == "get_aed_locations_for_egrid":
        egrid = params.get("egrid", "CH294676423526")  # Default EGRID auf Bundeshaus
        scale = params.get("scale", 1000)
        lang = params.get("lang", "de")
        url = f"DIPANU_DIPANUF_KMGDM1=DIPANUF_EGRID={egrid}&addcrosshair=false&scale={scale}&lang={lang}&layers=AEDSTO_AEDSTO_KMGDM1,AEDSTO_AEDSTO_KMGDM2&legend=True"

    if name_function == "get_river_zones_for_egrid":
        egrid = params.get("egrid", "CH294676423526")  # Default EGRID auf Bundeshaus
        scale = params.get("scale", 1000)
        lang = params.get("lang", "de")
        url = f"DIPANU_DIPANUF_KMGDM1=DIPANUF_EGRID={egrid}&addcrosshair=false&scale={scale}&lang={lang}&layers=GEWRGNHM_GEWRPOLY_KMGDM1,GEWRGNHM_GEWRPOLY_KMGDM2&legend=True"

    full_url = base_url + url
    return full_url

def get_center_from_bbox(params: dict):
    """Berechnet das Zentrum der Bounding-Box."""
    min_x, _, min_y, _ = get_coords_from_bbox(params)
    deltax, deltay = get_deltas_from_bbox(params)
    centerx = min_x + deltax / 2 if min_x is not None and deltax is not None else None
    centery = min_y + deltay / 2 if min_y is not None and deltay is not None else None
    return centerx, centery

def get_coords_from_bbox(params: dict):
    """Liest die Koordinaten der Bounding-Box aus dem Parameter dict."""
    min_x = params.get("min_x")
    max_x = params.get("max_x")
    min_y = params.get("min_y")
    max_y = params.get("max_y")
    return min_x, max_x, min_y, max_y

def get_deltas_from_bbox(params: dict):
    """Berechnet die Deltas (Breite und Höhe) der Bounding-Box."""
    min_x, max_x, min_y, max_y = get_coords_from_bbox(params)
    deltax = (max_x - min_x) if min_x is not None and max_x is not None else None
    deltay = (max_y - min_y) if min_y is not None and max_y is not None else None
    return deltax, deltay

def get_scale_from_bbox(params:dict):
    """Definiert den Kartenausschnitt-Massstab basierend auf den Bounding-Box Werten."""
    deltax, deltay = get_deltas_from_bbox(params)
    if deltax is None or deltay is None:
        scale = 1000
    else:
        if deltax > deltay:
            usdelta = deltax
        else:
            usdelta = deltay
        if usdelta < 100:
            scale = 1000
        elif usdelta < 1000:
            scale = 5000
        else:
            scale = 10000
    return scale